package app.manga.auth;
import app.manga.user.*;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.util.Locale;import java.util.Map;import org.springframework.http.HttpStatus;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/v1/auth") public class AuthController {private final UserRepository users;private final PasswordEncoder encoder;public AuthController(UserRepository u,PasswordEncoder e){users=u;encoder=e;}
 public record AuthBody(@NotBlank@Email@Size(max=254)String email,@NotBlank@Size(min=10,max=72)String password,String displayName){}
 @PostMapping("/register")public Object register(@Valid@RequestBody AuthBody b,HttpServletRequest req){String email=b.email().trim().toLowerCase(Locale.ROOT);if(users.existsByEmail(email))throw new ResponseStatusException(HttpStatus.CONFLICT,"Email sudah terdaftar.");String name=b.displayName()==null||b.displayName().isBlank()?email.substring(0,email.indexOf('@')):b.displayName().trim();if(name.length()>100)throw new IllegalArgumentException("Nama terlalu panjang.");AppUser u=users.save(new AppUser(email,encoder.encode(b.password()),name));authenticate(u,req);return Map.of("data",Map.of("email",u.getEmail(),"displayName",u.getDisplayName()));}
 @PostMapping("/login")public Object login(@Valid@RequestBody AuthBody b,HttpServletRequest req){String email=b.email().trim().toLowerCase(Locale.ROOT);AppUser u=users.findByEmail(email).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Email atau password tidak valid."));if(!encoder.matches(b.password(),u.getPasswordHash()))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Email atau password tidak valid.");authenticate(u,req);return Map.of("data",Map.of("email",u.getEmail(),"displayName",u.getDisplayName()));}
 private void authenticate(AppUser u,HttpServletRequest req){var auth=new UsernamePasswordAuthenticationToken(u.getEmail(),null,java.util.List.of(new org.springframework.security.core.authority.SimpleGrantedAuthority("ROLE_"+u.getRole())));SecurityContextHolder.getContext().setAuthentication(auth);req.getSession(true).setAttribute("SPRING_SECURITY_CONTEXT",SecurityContextHolder.getContext());}
}
